import pandas as pd
import numpy as np

def run(inputs: dict[str, pd.DataFrame]) -> dict[str, pd.DataFrame]:
    snap_prev = inputs["snap_prev"].copy()
    snap_curr = inputs["snap_curr"].copy()

    # Merge on key columns (region, sku) to find inserts, deletes, and updates
    merged = pd.merge(
        snap_prev,
        snap_curr,
        on=["region", "sku"],
        how="outer",
        suffixes=("_prev", "_curr"),
        indicator=True
    )

    rows = []

    for _, row in merged.iterrows():
        region = row["region"]
        sku = row["sku"]
        merge_indicator = row["_merge"]

        if merge_indicator == "left_only":
            # Key only in snap_prev -> DELETE
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "D",
                "changed_cols": None
            })
        elif merge_indicator == "right_only":
            # Key only in snap_curr -> INSERT
            rows.append({
                "region": region,
                "sku": sku,
                "change_type": "I",
                "changed_cols": None
            })
        else:
            # Key in both -> check if UPDATE is needed
            changed_cols_list = []

            # Compare price (NULL-safe, by value)
            price_prev = row["price_prev"]
            price_curr = row["price_curr"]
            if pd.isna(price_prev) and pd.isna(price_curr):
                price_equal = True
            elif pd.isna(price_prev) or pd.isna(price_curr):
                price_equal = False
            else:
                price_equal = (price_prev == price_curr)

            if not price_equal:
                changed_cols_list.append("price")

            # Compare stock (NULL-safe, by value)
            stock_prev = row["stock_prev"]
            stock_curr = row["stock_curr"]
            if pd.isna(stock_prev) and pd.isna(stock_curr):
                stock_equal = True
            elif pd.isna(stock_prev) or pd.isna(stock_curr):
                stock_equal = False
            else:
                stock_equal = (stock_prev == stock_curr)

            if not stock_equal:
                changed_cols_list.append("stock")

            # Compare label (trailing space insensitive, NULL-safe)
            label_prev = row["label_prev"]
            label_curr = row["label_curr"]

            # Handle NaN/None as NULL
            if pd.isna(label_prev):
                label_prev_str = None
            else:
                label_prev_str = label_prev

            if pd.isna(label_curr):
                label_curr_str = None
            else:
                label_curr_str = label_curr

            # Compare after RTRIM (trailing space removal)
            if label_prev_str is None and label_curr_str is None:
                label_equal = True
            elif label_prev_str is None or label_curr_str is None:
                label_equal = False
            else:
                label_prev_trimmed = label_prev_str.rstrip()
                label_curr_trimmed = label_curr_str.rstrip()
                label_equal = (label_prev_trimmed == label_curr_trimmed)

            if not label_equal:
                changed_cols_list.append("label")

            # Only emit row if there are changes
            if changed_cols_list:
                rows.append({
                    "region": region,
                    "sku": sku,
                    "change_type": "U",
                    "changed_cols": ",".join(changed_cols_list)
                })

    change_log = pd.DataFrame(rows)

    # Ensure correct column types
    if len(change_log) > 0:
        change_log = change_log.astype({
            "region": "object",
            "sku": "object",
            "change_type": "object",
            "changed_cols": "object"
        })
    else:
        change_log = pd.DataFrame(
            columns=["region", "sku", "change_type", "changed_cols"]
        )
        change_log = change_log.astype({
            "region": "object",
            "sku": "object",
            "change_type": "object",
            "changed_cols": "object"
        })

    return {"change_log": change_log}
